export const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
export function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
let timer;export function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
export const panelHeader=(label,title)=>`<header class="panel-header"><div><span class="overline">${label}</span><h2>${esc(title)}</h2></div><button class="close-button" data-action="close-panel" aria-label="关闭面板">${icon('close')}</button></header>`;
export const sourceButton=(id,label='查看原始资料')=>`<button class="source-link" data-source="${esc(id)}">${icon('source')}${esc(label)} ↗</button>`;
